CREATE TABLE IF NOT EXISTS research_outcomes (outcome_id UUID PRIMARY KEY, owner_id UUID NOT NULL REFERENCES users(owner_id) ON DELETE CASCADE, request_id UUID NOT NULL REFERENCES research_requests(request_id) ON DELETE CASCADE, status TEXT NOT NULL CHECK(status IN('pending','evaluated','ambiguous','insufficient_data')), observed_price NUMERIC(20,4), observed_at TIMESTAMPTZ, note TEXT, created_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP, UNIQUE(owner_id,request_id));
